import XCTest
@testable import FindMyRingKit

/// Cross-checks the Swift SRP port against vectors generated by the real Python
/// `srp` library as pyicloud drives it (rfc5054 + no_username_in_x + s2k/s2k_fo).
/// If any of these fail, the Swift sign-in would not match Apple's server.
final class SRPTests: XCTestCase {

    struct Vector {
        let username: String
        let password: String
        let saltHex: String
        let iterations: Int
        let proto: SRPClient.PasswordProtocol
        let aHex: String
        let bHex: String
        let expectedABase64: String
        let expectedM1Base64: String
        let expectedM2Base64: String
    }

    let vectors: [Vector] = [
        Vector(
            username: "djytest@example.com",
            password: "Corr3ct-Horse-Battery!",
            saltHex: "000102030405060708090a0b0c0d0e0f",
            iterations: 1000,
            proto: .s2k,
            aHex: "80" + String(repeating: "11", count: 255),
            bHex: bPatternHex(),
            expectedABase64: "",
            expectedM1Base64: "d4uBRjalfaqZvk3pmb2A4jYBN0CWG+rAPAoSKhqTsas=",
            expectedM2Base64: "I3jWswi8mQzLkdJCagCj/x2bz1k+Nw0c1KgNN0lnI7U="
        ),
        Vector(
            username: "djytest@example.com",
            password: "Corr3ct-Horse-Battery!",
            saltHex: "000102030405060708090a0b0c0d0e0f",
            iterations: 1000,
            proto: .s2k_fo,
            aHex: "80" + String(repeating: "11", count: 255),
            bHex: bPatternHex(),
            expectedABase64: "",
            expectedM1Base64: "Ev6fR69/kQhywEkkKP1KOabMagRty8ly0jQQqtTLPN8=",
            expectedM2Base64: "3KJECo+wL7bKPbEYCEIUUXYRgoGnMu7+ls94JjkFEnY="
        ),
    ]

    func testVectors() throws {
        for v in vectors {
            let client = SRPClient(
                username: v.username,
                privateEphemeral: Data(hex: v.aHex)
            )
            XCTAssertEqual(client.publicValueBase64, v.expectedABase64,
                           "A mismatch for \(v.proto.rawValue)")
            let proof = client.proof(
                password: v.password,
                salt: Data(hex: v.saltHex),
                serverPublicB: Data(hex: v.bHex),
                protocol: v.proto,
                iterations: v.iterations
            )
            XCTAssertEqual(proof.m1Base64, v.expectedM1Base64,
                           "M1 mismatch for \(v.proto.rawValue)")
            XCTAssertEqual(proof.m2Base64, v.expectedM2Base64,
                           "M2 mismatch for \(v.proto.rawValue)")
        }
    }
}

/// The 256-byte B pattern used by the vector generator: (i*7+3) mod 256.
private func bPatternHex() -> String {
    (0..<256).map { String(format: "%02x", ($0 * 7 + 3) & 0xFF) }.joined()
}

extension Data {
    init(hex: String) {
        var data = Data()
        var idx = hex.startIndex
        while idx < hex.endIndex {
            let next = hex.index(idx, offsetBy: 2)
            data.append(UInt8(hex[idx..<next], radix: 16)!)
            idx = next
        }
        self = data
    }
}
